package filo.afk.opacity;

import com.google.inject.Provides;
import javax.inject.Inject;
import javax.swing.*;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.NotificationFired;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.Text;

import java.awt.*;
import java.awt.event.AWTEventListener;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.HashMap;
import java.util.Map;

@Slf4j
@PluginDescriptor(
	name = "AFK Hider",
		description = "Hides the client upon clicking specified menu options"
)
public class AFKOpacityPlugin extends Plugin
{
	@Inject
	private Client client;
	@Inject
	private AFKOpacityConfig config;
	@Inject
	private ChatMessageManager chatMessageManager;

	private int idleRestoreTick = -1;
	private boolean afk = false;
	private boolean pendingRestore = false;
	private boolean usingTabbedOpacity = false;
	private Map<String, List<String>> interactions = new HashMap<>();

	// RuneLite Key Listener didn't work because of things like 'Press Enter to Chat...' was bugged
	private final AWTEventListener awtKeyListener = awtEvent ->
	{
		if (!afk || pendingRestore)
			return;

		if (awtEvent instanceof KeyEvent)
		{
			KeyEvent keyEvent = (KeyEvent) awtEvent;
			if (keyEvent.getID() == KeyEvent.KEY_PRESSED && keyEvent.getKeyCode() == config.escapeKeybind().getKeyCode())
			{
				keyEvent.consume();
				escapeAfkMode("due to restore key");
				return;
			}

			if (!config.preventKeyInput())
				return;

			if (keyEvent.getID() != KeyEvent.KEY_PRESSED
					&& keyEvent.getID() != KeyEvent.KEY_TYPED)	// Release is fine and prevents camera key stuck thing
			{
				return;
			}

			keyEvent.consume();
		}
	};

	private final AWTEventListener awtMouseListener = awtEvent ->
	{
		if (!afk || !config.preventClickInput() || pendingRestore)
			return;

		if (awtEvent instanceof MouseWheelEvent)
		{
			MouseWheelEvent mouseWheelEvent = (MouseWheelEvent) awtEvent;
			mouseWheelEvent.consume();
			return;
		}

		if (awtEvent instanceof MouseEvent)
		{
			MouseEvent mouseEvent = (MouseEvent) awtEvent;

			if (mouseEvent.getID() == MouseEvent.MOUSE_CLICKED
			|| mouseEvent.getID() == MouseEvent.MOUSE_PRESSED
			|| mouseEvent.getID() == MouseEvent.MOUSE_RELEASED
			)
			{
				mouseEvent.consume();
			}
		}
	};

	@Override
	protected void startUp() throws Exception
	{
		interactions = parseConfig();
		Toolkit.getDefaultToolkit().addAWTEventListener(awtKeyListener, AWTEvent.KEY_EVENT_MASK);
		Toolkit.getDefaultToolkit().addAWTEventListener(awtMouseListener, AWTEvent.MOUSE_EVENT_MASK | AWTEvent.MOUSE_WHEEL_EVENT_MASK);
	}

	@Override
	protected void shutDown() throws Exception
	{
		Toolkit.getDefaultToolkit().removeAWTEventListener(awtKeyListener);
		Toolkit.getDefaultToolkit().removeAWTEventListener(awtMouseListener);
		escapeAfkMode(null);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!event.getGroup().equals("filoafkhider"))
			return;

		if (event.getKey().equals("interaction")) {
			interactions = parseConfig();
		}
	}

	@Subscribe
	public void onGameTick(GameTick e)
	{
		if (pendingRestore) {
			escapeAfkMode(null);
			return;
		}

		if (!afk)
			return;

		if (config.idleRestore() > 0
				&& idleRestoreTick != -1
				&& client.getTickCount() >= idleRestoreTick)
		{
			escapeAfkMode("due to Idle Timeout config");
			return;
		}

		if (!isClientFocused())
		{
			if (config.restoreOnFocusLoss())
			{
				escapeAfkMode("due to focus loss");
				return;
			}

			if (!usingTabbedOpacity)
			{
				updateAfkOpacity(config.afkTabbedOpacity() / 100f);
				usingTabbedOpacity = true;
			}

			return;
		}

		if (usingTabbedOpacity)
		{
			updateAfkOpacity(config.afkOpacity() / 100f);
			usingTabbedOpacity = false;
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		String eventOption = event.getMenuOption();
		String eventTarget = event.getMenuTarget();

		if (eventOption == null || eventTarget == null || eventOption.isEmpty() || eventTarget.isEmpty())
			return;

		String option = Text.removeTags(eventOption);
		String target = Text.removeTags(eventTarget);

		if (option.isEmpty() || target.isEmpty())
			return;

		if (config.logActions()) {
			addChatMessage("AFK Hider Action: " + option + ":" + target);
		}

		// Like 100% sure AWT mouse thing prevents this based on testing, but why not be safe?
		if (afk && config.preventClickInput() && !pendingRestore)
		{
			event.consume();
			return;
		}

		String optionStandardized = option.toLowerCase();
		String targetStandardized = target.toLowerCase();

		if (interactions.containsKey(optionStandardized)
				&& interactions.get(optionStandardized).contains(targetStandardized))
		{
				enterAfkMode();
		}
	}

	private Map<String, List<String>> parseConfig() {
		Map<String, List<String>> tmpInteractions = new HashMap<>();
		String interactionConfig = config.interaction();

		for (String line : interactionConfig.split("\n")) {
			line = line.trim().toLowerCase();
			if (line.isEmpty()) {
				continue;
			}

			String[] lineParts = line.split(":", 2);
			if (lineParts.length != 2) {
				continue;
			}

			String action = lineParts[0].trim();
			String target = lineParts[1].trim();

			tmpInteractions.putIfAbsent(action, new ArrayList<>());
			tmpInteractions.get(action).add(target);
		}

		return tmpInteractions;
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (!afk)
			return;

		if (event.getActor() instanceof Player)
		{
			Player targetPlayer = (Player) event.getActor();
			if (targetPlayer == client.getLocalPlayer())
			{
				if (config.restoreOnHitsplat()) {
					escapeAfkMode("due to a hitsplat");
				}
			}
		}
	}

	@Subscribe
	public void onNotificationFired(NotificationFired e)
	{
		if (config.restoreOnNotify()) {
			escapeAfkMode("due to notification");
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		if (e.getGameState() == GameState.LOGIN_SCREEN) {
			escapeAfkMode(null);
		}
	}

	private boolean isClientFocused()
	{
		Frame frame = getClientFrame();
		Canvas canvas = client.getCanvas();

		if (frame == null || canvas == null)
			return false;

		return (frame.isFocused() || frame.isActive()) || canvas.hasFocus();
	}

	private Frame getClientFrame()
	{
		Window clientWindow = SwingUtilities.getWindowAncestor(client.getCanvas());

		if (clientWindow instanceof Frame)
			return (Frame) clientWindow;

		return null;
	}

	private void addChatMessage(String message)
	{
		String chatMessage = new ChatMessageBuilder()
				.append(ChatColorType.NORMAL)
				.append(message)
				.build();

		chatMessageManager.queue(QueuedMessage
				.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage(chatMessage)
				.build()
		);
	}

	private boolean checkInventorySpace()
	{
		if (!config.preventFullInventory())
			return true;

		ItemContainer invContainer = client.getItemContainer(InventoryID.INV);
        return invContainer != null && invContainer.count() < 28;
    }

	@Provides
	AFKOpacityConfig provideConfig(ConfigManager configManager) {
		return configManager.getConfig(AFKOpacityConfig.class);
	}

	private boolean setFrameOpacity(float opacity)
	{
		Frame frame = getClientFrame();
		if (frame == null)
			return false;

		try
		{
			frame.setOpacity(opacity);
			return Math.abs(frame.getOpacity() - opacity) < 0.001f; // Just being safe here but realistically could just use ==
		}
		catch (RuntimeException e)
		{
			return false;
		}
	}

	private void enterAfkMode()
	{
		if (!checkInventorySpace())
			return;

		float opacity = config.afkOpacity() / 100f;
		if (!setFrameOpacity(opacity))
		{
			addChatMessage("AFK Hider: Failed to enter AFK mode.");
			return;
		}

		afk = true;
		pendingRestore = false;
		usingTabbedOpacity = false;

		if (config.idleRestore() > 0) {
			idleRestoreTick = client.getTickCount() + (config.idleRestore() * 100);
		}
	}

	private void updateAfkOpacity(float opacity)
	{
		if (!afk)
			return;

		setFrameOpacity(opacity);
	}

	private void escapeAfkMode(String reason)
	{
		if (!afk)
			return;

		if (!setFrameOpacity(1f))
		{
			if (!pendingRestore) {
				addChatMessage("AFK Hider: Input restored. Still trying to restore window opacity.");
			}

			pendingRestore = true;
			return;
		}

		afk = false;
		usingTabbedOpacity = false;
		pendingRestore = false;
		idleRestoreTick = -1;

		if (config.printReason() && reason != null) {
			addChatMessage("AFK Hider: Reason: " + reason);
		}
	}
}

package filo.afk.opacity;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;
import java.awt.event.KeyEvent;

@ConfigGroup("filoafkhider")
public interface AFKOpacityConfig extends Config
{
	//region Sections
	@ConfigSection(
			name = "Help",
			description = "Help inside. If you accidentally delete you can right-click reset the 'help' label.",
			position = 0,
			closedByDefault = true
	)
	String helpSettings = "Help";

	@ConfigSection(
			name = "Main",
			description = "Main settings for AFK Hider",
			position = 1
	)
	String generalSettings = "Main Settings";

	@ConfigSection(
			name = "Restore Settings",
			description = "Change what can restore the client",
			position = 2
	)
	String restoreSettings = "Restore Settings";

	@ConfigSection(
			name = "Input Settings",
			description = "Change how AFK mode changes inputs",
			position = 3
	)
	String inputSettings = "Input Settings";

	@ConfigSection(
			name = "Debug",
			description = "Simple debug settings",
			position = 4,
			closedByDefault = true
	)
	String debugSettings = "Debug Settings";
	//endregion

	//region help
	@ConfigItem(
			keyName = "help",
			name = "Help:",
			description = "Options that activate AFK mode. One per line, format is 'option:target'.",
			section = helpSettings,
			position = 0
	)
	default String help()
	{
		return "### Help ###\n"
				+ "This plugin will change the opacity of the client when you click an action specified in 'Triggers'\n\n"
				+ "Formatted as: 'option:target'. It is not case-sensitive and one per line\n\n"
				+ "Examples:\n"
				+ "mine:crashed star\n"
				+ "chop down:ironwood tree\n\n"
				+ "You can set the opacity to 0 to make the client invisible while AFK mode is active.\n\n"
				+ "If you wish to restore the client you must use one of the following:\n"
				+ "1. Restore Keybind - Only works when RuneLite is focused\n"
				+ "2. Restore on Notification - When RuneLite notifies you\n"
				+ "3. Restore on Hitsplat - When your player takes a hitsplat\n"
				+ "4. Restore on Focus Loss - When you tab-out if enabled.\n"
				+ "5. Idle Restore Delay - Delay in minutes before the client will restore itself\n\n"
				+ "Be careful using this plugin in dangerous locations";
	}
	//endregion

	//region General
	@ConfigItem(
			keyName = "interaction",
			name = "Triggers",
			description = "Options that activate AFK mode. One per line, format is 'option:target'.",
			section = generalSettings,
			position = 0
	)
	default String interaction()
	{
		return "";
	}

	@Range(min = 1, max = 100)
	@ConfigItem(
			keyName = "afkOpacity",
			name = "Afk Opacity",
			description = "Client opacity while AFK mode is active.",
			section = generalSettings,
			position = 1
	)
	default int afkOpacity()
	{
		return 20;
	}

	@Range(min = 1, max = 100)
	@ConfigItem(
			keyName = "afkTabbedOpacity",
			name = "Tabbed Out Opacity",
			description = "Client opacity while AFK mode is active and the game is not focused.",
			section = generalSettings,
			position = 2
	)
	default int afkTabbedOpacity()
	{
		return 50;
	}


	@ConfigItem(
			keyName = "escapeKeybind",
			name = "Restore Keybind",
			description = "Keybind used to restore from AFK mode",
			section = generalSettings,
			position = 3
	)
	default Keybind escapeKeybind()
	{
		return new Keybind(KeyEvent.VK_ESCAPE, 0);
	}
	//endregion
	//region Restore
	@ConfigItem(
			keyName = "restoreOnNotify",
			name = "Restore on Notification",
			description = "Restore the client when a RuneLite notification happens",
			section = restoreSettings,
			position = 0
	)
	default boolean restoreOnNotify()
	{
		return true;
	}

	@ConfigItem(
			keyName = "restoreOnHitsplat",
			name = "Restore on Hitsplat",
			description = "Restore the client when your player receives a hitsplat",
			section = restoreSettings,
			position = 1
	)
	default boolean restoreOnHitsplat()
	{
		return true;
	}

	@ConfigItem(
			keyName = "restoreOnFocusLoss",
			name = "Restore on Focus Loss",
			description = "Restore the client when the game loses focus",
			section = restoreSettings,
			position = 2
	)
	default boolean restoreOnFocusLoss()
	{
		return false;
	}

	@Range(min = 0, max = 30)
	@ConfigItem(
			keyName = "idleRestore",
			name = "Idle Restore Delay",
			description = "Restore the client after this many minutes in AFK mode. Set to 0 to disable.",
			section = restoreSettings,
			position = 3
	)
	@Units(Units.MINUTES)
	default int idleRestore()
	{
		return 0;
	}
	//endregion
	//region Input
	@ConfigItem(
			keyName = "preventClickInput",
			name = "Block Cursor Input",
			description = "Block all mouse input while AFK mode is active.",
			section = inputSettings,
			position = 0
	)
	default boolean preventClickInput()
	{
		return true;
	}

	@ConfigItem(
			keyName = "preventKeyInput",
			name = "Block Keyboard Input",
			description = "Block all keyboard input while AFK mode is active. The restore key still works.",
			section = inputSettings,
			position = 1
	)
	default boolean preventKeyInput()
	{
		return true;
	}

	@ConfigItem(
			keyName = "preventFullInventory",
			name = "Require Inventory Space",
			description = "Prevent entering AFK mode if your inventory is full",
			section = inputSettings,
			position = 2

	)
	default boolean preventFullInventory()
	{
		return true;
	}
	//endregion
	//region debug
	@ConfigItem(
			keyName = "logActions",
			name = "Log Actions to Chat",
			description = "Print clicked options to the chat to help configure Triggers.",
			section = debugSettings,
			position = 0
	)
	default boolean logActions()
	{
		return false;
	}

	@ConfigItem(
			keyName = "printReason",
			name = "Print Restore Reason",
			description = "Print the reason the client restored to the chat",
			section = debugSettings,
			position = 1
	)
	default boolean printReason()
	{
		return true;
	}
	//endregion
}
